/// An inline box with an `opacity` below one is composited as a group, as in CSS: its background, border,
/// glyphs and what its descendants paint are drawn opaque into a layer that is faded as a whole, so the glyphs over
/// the box's own background do not show it through twice. The colours are the ones headless Chrome paints
/// (`fixtures/inline-opacity-oracle.json`, regenerated by `fixtures/inline-opacity-oracle.sh`).

import fs from "fs"
import path from "path"
import React from "react"
import { fileURLToPath } from "url"
import { describe, expect, it } from "vitest"
import { createTestRoot, hasNativeTestRenderer } from "../testing.js"
import { readLogicalPixels, SHOTS_DIR } from "./test-utils.js"

const describeNative = hasNativeTestRenderer ? describe : describe.skip

type Rgb = [number, number, number]

const ORACLE: Record<string, { colors: Record<string, Rgb> }> = JSON.parse(
  fs.readFileSync(path.resolve(path.dirname(fileURLToPath(import.meta.url)), "fixtures/inline-opacity-oracle.json"), "utf8")
).cases

const TEXT = { color: "#000000", fontFamily: "Helvetica", fontSize: 48, fontWeight: 700, lineHeight: "60px", width: 300, paddingTop: 0 } as const
const PADDING = { paddingLeft: 12 }

/** The spans of each case of the oracle: `testId` names the span whose points the oracle has. */
const CASES: Record<string, React.ReactNode> = {
  "text over its own background": (
    <span testId="a" style={{ opacity: 0.5, backgroundColor: "#f00", color: "#00f", ...PADDING }}>MM</span>
  ),
  "opacity 0.25": (
    <span testId="a" style={{ opacity: 0.25, backgroundColor: "#f00", color: "#00f", ...PADDING }}>MM</span>
  ),
  "full opacity is no group": (
    <span testId="a" style={{ opacity: 1, backgroundColor: "#f00", color: "#00f", ...PADDING }}>MM</span>
  ),
  "nested groups": (
    <span testId="outer" style={{ opacity: 0.5, backgroundColor: "#f00", ...PADDING }}>
      <span testId="inner" style={{ opacity: 0.5, backgroundColor: "#0f0", color: "#00f", ...PADDING }}>MM</span>
    </span>
  ),
  "a box inside a faded box": (
    <span testId="outer" style={{ opacity: 0.5, backgroundColor: "#f00", color: "#00f", ...PADDING }}>
      <span testId="inner" style={{ backgroundColor: "#0f0", ...PADDING }}>MM</span>
    </span>
  ),
  "a faded box after another": (
    <>
      <span testId="first" style={{ backgroundColor: "#f00", color: "#00f", ...PADDING }}>M</span>
      <span testId="second" style={{ opacity: 0.5, backgroundColor: "#0f0", ...PADDING }}>M</span>
    </>
  ),
}

let shots = 0

/** The colour at each point the oracle names, found from the bounds of the span of that name. */
function painted(name: string): Record<string, Rgb> {
  const testRoot = createTestRoot({ width: 300, height: 80 })
  try {
    testRoot.render(
      <div style={{ width: 300, height: 80, backgroundColor: "#ffffff" }}>
        <text testId="p" style={TEXT as never}>
          {CASES[name]}
        </text>
      </div>
    )
    const renderer = testRoot.renderer
    const file = `${SHOTS_DIR}/inline-opacity-${shots++}.png`
    renderer.captureScreenshot(file)
    const pixels = readLogicalPixels(file, renderer)
    const paragraph = renderer.getElementBounds(renderer.findByTestId("p")!.id)!
    const colors: Record<string, Rgb> = {}
    for (const point of Object.keys(ORACLE[name]!.colors)) {
      const [span, kind] = point.split(" ") as [string, "padding" | "stem"]
      const box = renderer.getElementBounds(renderer.findByTestId(span)!.id)!
      // The oracle samples 30px below the top of the line.
      const x = Math.round(kind === "padding" ? box.x + 4 : box.x + PADDING.paddingLeft + 7)
      colors[point] = pixels.at(x, Math.round(paragraph.y + 30)).slice(0, 3) as Rgb
    }
    return colors
  } finally {
    testRoot.unmount()
  }
}

describeNative("opacity of an inline box against Chrome", () => {
  for (const name of Object.keys(CASES)) {
    it(name, () => {
      const colors = painted(name)
      for (const [point, expected] of Object.entries(ORACLE[name]!.colors)) {
        colors[point]!.forEach((channel, index) => {
          expect(Math.abs(channel - expected[index]!), `${name} / ${point}: ${colors[point]} against ${expected}`).toBeLessThanOrEqual(3)
        })
      }
    })
  }
})
